// ---------------------------------------------------------------------------
// Spirograph Live — generated by Dialcraft
// target: Amazfit Bip 6 (bip-6, 390×450, s)
//
// Built against the Zepp OS watchface API:
//   widgets  https://docs.zepp.com/docs/watchface/api/hmUI/widget/
//   layout   px() scales from app.json designWidth = 390
//   states   show_level = normal / AOD / edit
// Design-spec reminders: preview time 10:09:36, 2px safe edge, AOD keeps
// the pixel budget under 10% with a black background and no second hand.
// ---------------------------------------------------------------------------
import ui from '@zos/ui'

const A = (p) => `images/${p}`

// ---- image arrays (frame order matters: digits 0-9, week 1-7) ----
const img_Minute_a14g = [
  A('font_1_0.png'),
  A('font_1_1.png'),
  A('font_1_2.png'),
  A('font_1_3.png'),
  A('font_1_4.png'),
  A('font_1_5.png'),
  A('font_1_6.png'),
  A('font_1_7.png'),
  A('font_1_8.png'),
  A('font_1_9.png'),
]

const img_Hour_a38k = [
  A('font_2_0.png'),
  A('font_2_1.png'),
  A('font_2_2.png'),
  A('font_2_3.png'),
  A('font_2_4.png'),
  A('font_2_5.png'),
  A('font_2_6.png'),
  A('font_2_7.png'),
  A('font_2_8.png'),
  A('font_2_9.png'),
]

WatchFace({
  initView() {
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Spirograph canvas 1 (CANVAS)
    const canvas_1 = ui.createWidget(ui.widget.CANVAS, {
      x: px(50),
      y: px(135),
      w: px(290),
      h: px(290),
      show_level: ui.show_level.ONLY_NORMAL,
    })
    canvas_1.setAlpha(240)
    W.k1 = canvas_1

    // Spirograph canvas 2 (CANVAS)
    const canvas_2 = ui.createWidget(ui.widget.CANVAS, {
      x: px(50),
      y: px(135),
      w: px(290),
      h: px(290),
      show_level: ui.show_level.ONLY_NORMAL,
    })
    canvas_2.setAlpha(195)
    W.k2 = canvas_2

    // Spirograph canvas 3 (CANVAS)
    const canvas_3 = ui.createWidget(ui.widget.CANVAS, {
      x: px(50),
      y: px(135),
      w: px(290),
      h: px(290),
      show_level: ui.show_level.ONLY_NORMAL,
    })
    canvas_3.setAlpha(150)
    W.k3 = canvas_3

    // Minute (IMG_TIME) — normal state
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(196),
      minute_startY: px(39),
      minute_zero: 1,
      minute_space: px(-6),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_a14g,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute (IMG_TIME) — AOD (screen-off)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(196),
      minute_startY: px(39),
      minute_zero: 1,
      minute_space: px(-6),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_a14g,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon (IMG) — normal state
    ui.createWidget(ui.widget.IMG, {
      x: px(178),
      y: px(46),
      src: A('symbol_u003a.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Colon (IMG) — AOD (screen-off)
    ui.createWidget(ui.widget.IMG, {
      x: px(178),
      y: px(46),
      src: A('symbol_u003a.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Hour (IMG_TIME) — normal state
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(68),
      hour_startY: px(39),
      hour_zero: 1,
      hour_space: px(-6),
      hour_align: ui.align.RIGHT,
      hour_array: img_Hour_a38k,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour (IMG_TIME) — AOD (screen-off)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(68),
      hour_startY: px(39),
      hour_zero: 1,
      hour_space: px(-6),
      hour_align: ui.align.RIGHT,
      hour_array: img_Hour_a38k,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Tap for a new spirograph (TEXT)
    W.tap = ui.createWidget(ui.widget.TEXT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0xffffff,
      text_size: px(32),
      align_h: ui.align.CENTER_H,
      align_v: ui.align.CENTER_V,
      text: "",
      show_level: ui.show_level.ONLY_NORMAL,
    })


    // ---- user code (project.userCode) ----
    // SP: live spirographs (watch-portable: plain ES5 maths; the watch draws them with drawLine on 3 setAlpha canvases).
    // A curve is a hypotrochoid: a wheel of r teeth rolls inside a ring of R teeth, the pen sits d from the wheel's centre:
    //   x = (R-r) cos t + d cos((R-r)/r t),  y = (R-r) sin t - d sin((R-r)/r t),  closing after n = r / gcd(R, r) turns.
    // All 3 curves of a pattern share the ring R (so they nest) but have their own wheel, pen distance, turn and colour.
    var SP = (function () {
      function rng(seed) { var a = seed >>> 0; return function () { a = (a + 0x6d2b79f5) >>> 0; var t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296 } }
      function hsl(h, sat, l) { h = ((h % 360) + 360) % 360; var a = sat * Math.min(l, 1 - l), f = function (n) { var k = (n + h / 30) % 12, v = l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1)); return Math.round(v * 255) }; return (f(0) << 16) | (f(8) << 8) | f(4) }
      function gcd(a, b) { return b ? gcd(b, a % b) : a }
      // seed -> { P: palette name, ring: R, curves: [{ n, P (segments), color, w, pt(i) -> [x, y] }] }
      function make(seed, opt) {
        var r = rng(seed), pick = function (a) { return a[Math.floor(r() * a.length)] }
        var cx = (opt && opt.cx) || 195, cy = (opt && opt.cy) || 225, FIT = (opt && opt.fit) || 182
        var h0 = r() * 360                   // the rainbow starts at a random hue; the 3 curves are 120 deg apart
        var curves = [], ph = -Math.PI / 2, donut = r() < 0.5, L = 0
        // one curve: a hypotrochoid in gear units (ring Rg, wheel rg, pen d), turned by ph, scaled so its reach is `reach` px
        function curve(Rg, rg, d, reach, hue, P) {
          var tab = []; for (var q = 0; q < 48; q++) tab.push(hsl(hue + q * 7.5, 1, 0.68))      // one full turn of the colour wheel along the stroke
          var n = rg / gcd(Rg, rg), s = reach / ((Rg - rg) + d), k = (Rg - rg) / rg
          return { n: n, P: P, R: Rg, r: rg, d: Math.round(d * 10) / 10, color: tab[0], col: function (i) { return tab[Math.floor(48 * i / P) % 48] }, w: 2,
            pt: function (i) { var t = Math.PI * 2 * n * i / P, a = (Rg - rg) * Math.cos(t) + d * Math.cos(k * t), b = (Rg - rg) * Math.sin(t) - d * Math.sin(k * t)
              return [Math.round(cx + s * (a * Math.cos(ph) - b * Math.sin(ph))), Math.round(cy + s * (a * Math.sin(ph) + b * Math.cos(ph)))] } }
        }
        if (donut) {
          // DONUTS (like a spirograph sheet): three concentric dense rings with a hole, each with many lobes (L) and a few turns (n). The hole is
          // set by the pen distance: inner radius / outer radius = (Rg - rg - d) / (Rg - rg + d). Every ring is L-fold symmetric and mirror-symmetric.
          var outer = FIT, spec = [[20, 34, 0.55, 0.12], [14, 24, 0.5, 0.12], [9, 15, 0.2, 0.2]]
          for (var c = 0; c < 3; c++) {
            var lo = spec[c][0], hi = spec[c][1], Ld, nd, tries = 0
            // many turns (n about 30-45% of L, coprime with L) so the ring fills with a dense mesh
            do { Ld = lo + Math.floor(r() * (hi - lo + 1)); nd = Math.max(3, Math.round(Ld * (0.3 + r() * 0.15))); tries++ } while (tries < 200 && gcd(Ld, nd) !== 1)
            var h = spec[c][2] + r() * spec[c][3], gap = Ld - nd, d = gap * (1 - h) / (1 + h)
            curves.push(curve(Ld, nd, d, outer, h0 + c * 120, Math.max(420, Math.min(900, Ld * 20))))
            outer = outer * h - 6; if (c === 0) L = Ld
          }
        } else {
          // LOOPED ROSETTES: one lobe count L for the pattern (ring = L gear units, wheel = n units, n < L and coprime with L, so a curve has
          // exactly L lobes), mostly one turn, a different pen distance per curve (> 1 wheel: looped petals). All curves start at the same angle
          // on the +x axis (a mirror axis of every hypotrochoid) and the pattern is turned so a lobe points up: L-fold AND mirror symmetric.
          L = pick([5, 5, 6, 7, 7, 8])
          for (var c2 = 0; c2 < 3; c2++) {
            var n2 = (L % 2 && r() < 0.34) ? 2 : 1, rr = n2 * 16, Rg = L * 16
            var d2 = rr * (1.1 + (c2 + r() * 0.9) * 0.8)
            curves.push(curve(Rg, rr, d2, FIT * (c2 === 0 ? 1 : 0.84 + r() * 0.16), h0 + c2 * 120, 600))
          }
        }
        return { seed: seed, L: L, mode: donut ? 'donut' : 'loops', curves: curves, info: (donut ? 'donut' : 'loops') + ' L' + L + ' h' + Math.round(h0) + ' ' + curves.map(function (c) { return c.R + '/' + c.n }).join(' ') }
      }
      return { make: make }
    })()

    const DEBUG = false                                      // true: log to the developer bridge
    const say = (m) => { if (DEBUG) console.log('[sp] ' + m) }
    const C = [W.k1, W.k2, W.k3]                            // the three Canvas layers of the layout (code handles k1..k3)
    const DUR = 2500
    const LN = { x1: 0, y1: 0, x2: 0, y2: 0, color: 0 }, PT = { color: 0, line_width: 2 }
    let V = null, timer = null, t0 = 0, done = [0, 0, 0], last = [null, null, null], frames = 0
    const tick = () => {
      timer = null
      const ms = Date.now() - t0, prog = Math.min(1, ms / DUR)
      try {
        for (let c = 0; c < 3; c++) {
          const cu = V.curves[c], tgt = Math.floor(prog * cu.P)
          if (tgt <= done[c]) continue
          PT.color = cu.color; PT.line_width = cu.w; C[c].setPaint(PT)           // the brush sets the width; each segment gets its own rainbow colour
          while (done[c] < tgt) {
            done[c]++
            const p = cu.pt(done[c]), q = last[c]
            LN.x1 = q[0]; LN.y1 = q[1]; LN.x2 = p[0]; LN.y2 = p[1]; LN.color = cu.col(done[c])
            C[c].drawLine(LN); last[c] = p
          }
        }
      } catch (e) { say('draw: ' + e); return }
      frames++
      if (prog < 1) timer = setTimeout(tick, 0)
      else say(Math.round(frames * 1000 / ms) + ' fps, ' + V.info)
    }
    // pause / resume: pulling down the notification shade pauses the face just like the screen turning off, so a short absence only carries on; a longer one
    // (a real wake-up) starts a new drawing
    const WAKE_GAP = 8000
    let pausedAt = 0, startedAt = 0
    const stop = () => { if (timer) { try { clearTimeout(timer) } catch (e) {} timer = null } }
    const start = () => {
      stop(); startedAt = Date.now()
      const seed = ((Date.now() & 0x7fffffff) ^ Math.floor(Math.random() * 0x7fffffff)) >>> 0
      try {
        V = SP.make(seed, { cx: 145, cy: 145, fit: 140 })
        C.forEach((cv) => cv.clear({ x: 0, y: 0, w: 290, h: 290 }))
        done = [0, 0, 0]; last = V.curves.map((cu) => cu.pt(0))
      } catch (e) { say('make: ' + e); return }
      t0 = Date.now(); frames = 0; tick()
    }
    try { W.tap.addEventListener(ui.event.CLICK_UP, start) } catch (e) { say('tap: ' + e) }       // the empty full-screen Text layer on top (handle tap)
    const onPause = () => { if (Date.now() - startedAt < 1500) return; pausedAt = Date.now(); stop() }   // switching faces: the watch pauses and resumes the new face right after it loads, so a pause that early must not stop the loop
    const onResume = () => {
      const n = Date.now()
      if (n - startedAt < 1500) return                       // the watch also calls resume once when the face loads
      if (n - pausedAt >= WAKE_GAP) { start(); return }
      t0 += n - pausedAt; if (V && done.some((d, i) => d < V.curves[i].P)) tick()                    // a drawing in progress carries on
    }
    ui.createWidget(ui.widget.WIDGET_DELEGATE, { pause_call: onPause, resume_call: onResume })
    start()

    // ---- screen corners (the face switcher draws the live face square) ----
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(0), w: px(86), h: px(86), src: A('corner_tl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(0), w: px(86), h: px(86), src: A('corner_tr.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(364), w: px(86), h: px(86), src: A('corner_bl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(364), w: px(86), h: px(86), src: A('corner_br.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
  },

  build() {
    this.initView()
  },
})
